package dev.altencir.orders.api;
import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.util.UUID; import org.slf4j.MDC; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class CorrelationIdFilter extends OncePerRequestFilter { public static final String HEADER="X-Correlation-Id"; @Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{var id=request.getHeader(HEADER);if(id==null||id.isBlank())id=UUID.randomUUID().toString();response.setHeader(HEADER,id);try(MDC.MDCCloseable ignored=MDC.putCloseable("correlationId",id)){chain.doFilter(request,response);}} }
